{
  "API_calls": [],
  "collected_information": {
    "Dockerfile": {
      "base_image": "nikolaik/python-nodejs:python3.9-nodejs20-slim",
      "apt_packages": ["libgomp1", "git", "chromium", "multiple fonts", "libxss1"],
      "environment_variables": {
        "CHROME_BIN": "/usr/bin/chromium",
        "puppeteer_config": "/app/metagpt/config/puppeteer-config.json",
        "PUPPETEER_SKIP_CHROMIUM_DOWNLOAD": "true"
      },
      "node_global_install": "@mermaid-js/mermaid-cli",
      "python_setup": {
        "project_directory": "/app/metagpt",
        "working_directory": "/app/metagpt",
        "workspace_directory": "created inside project",
        "dependencies_install_command": "pip install -r requirements.txt --no-cache-dir",
        "editable_install_command": "pip install -e ."
      },
      "docker_cmd": "tail -f /dev/null"
    },
    "README.md": {
      "python_version": "3.9+",
      "conda_env_recommendation": "optional, no conda env file",
      "installation": [
        "pip install --upgrade metagpt",
        "pip install --upgrade git+https://github.com/geekan/MetaGPT.git",
        "clone and pip install -e ."
      ],
      "config_init_command": "metagpt --init-config",
      "test_commands": "none explicitly given",
      "dependencies": "external LLM API keys configured in config"
    },
    "requirements.txt": {
      "dependencies": [
        "aiohttp==3.8.6",
        "channels==4.0.0",
        "fire==0.4.0",
        "numpy==1.24.3",
        "openai==1.6.1",
        "pandas==2.0.3",
        "pydantic==2.5.3"
      ],
      "test_dependencies": "pytest==7.2.2, pytest-mock==3.11.1 commented out"
    },
    "CI_workflows": {
      "unittest.yaml": {
        "python_version": "3.9",
        "dependency_install": "sh tests/scripts/run_install_deps.sh",
        "environment_variables": {
          "ALLOW_OPENAI_API_CALL": "0"
        },
        "config_copy": "tests/config2.yaml to ~/.metagpt/config2.yaml",
        "test_command": "pytest tests/ --doctest-modules --cov=./metagpt/ --cov-report=xml:cov.xml --cov-report=html:htmlcov --durations=20 | tee unittest.txt"
      },
      "fulltest.yaml": {
        "extra_secret_decoding": ["config/key.yaml", "config2.yaml"]
      },
      "build-package.yaml": {
        "python_version": "3.9",
        "no_test_exec": true
      },
      "pre-commit.yaml": {
        "python_version": "3.9.17",
        "runs_pre_commit_hooks": true,
        "no_test_exec": true
      }
    },
    "tests_folder": {
      "contents": ["config files", "conftest.py", "subfolders"],
      "no_explicit_test_instructions": true
    },
    "no_conda_env_file": true,
    "no_CONTRIBUTING_md": true,
    "test_command_summary": "pytest with coverage and doctest, can specify tests individually manually"
  },
  "terminate": true
}
